    # ------------------------------------------------------------------ A-REI.B.4.a (derivation, new in 2.0.0)
    S('HSA-REI.B.4.a', 'Derive the quadratic formula by completing the square', num=71,
      main=[
          work('Derive the quadratic formula. Start from ax² + bx + c = 0 with a ≠ 0, and complete the square to solve for x.', 'x =',
               method='Every step shown: divide by a; subtract c ÷ a; add (b ÷ (2a))² to both sides; write (x + b ÷ (2a))² = (b² - 4ac) ÷ (4a²); take square roots, using ±; subtract b ÷ (2a).',
               key='x = (-b ± √(b² - 4ac)) ÷ (2a)', note='Form required: the complete derivation with every step, ending in the quadratic formula.'),
          work('The equation x² + (b ÷ a)x = -c ÷ a comes from ax² + bx + c = 0. What must be added to both sides to complete the square, and what does the left side become?', 'Answer:',
               method='Half of the x-coefficient, b ÷ (2a), squared: (b ÷ (2a))² = b² ÷ (4a²); then the left side factored as a square.',
               key='Add b² ÷ (4a²); the left side becomes (x + b ÷ (2a))².', note='Form required: the number added and the squared binomial.'),
          sa('After completing the square, (x + b ÷ (2a))² = (b² - 4ac) ÷ (4a²). Explain how taking square roots of both sides gives the ± and the denominator 2a.', 'Explanation:',
             key='Both the positive and the negative square roots of the right side work, so x + b ÷ (2a) = ±√(b² - 4ac) ÷ √(4a²). √(4a²) = 2|a|, and the ± already covers both signs, so the denominator can be written 2a.',
             note='Any equivalent explanation that mentions both square roots and √(4a²) = 2|a|.'),
          mc('In the derivation of the quadratic formula, why must a ≠ 0?', ['The first step divides by a, and if a = 0 the equation is not quadratic.', 'Because b must be positive.',
             'Because c must be 0.', 'Because the discriminant must be positive.'], note='Dividing by 0 is not allowed; with a = 0 the equation is linear.'),
          tf('The derivation shows that when b² - 4ac < 0, the equation has no real solutions.', key=True,
             note='The right side (b² - 4ac) ÷ (4a²) is negative, but a square of a real number is never negative.'),
      ],
      back=[
          B('Complete the square in expressions', 'HSA-SSE.B.3.b', [
              sa('Complete the square.\nx² + 12x + 7', 'Expression:', key='(x + 6)² - 29', note='Form required: (x - h)² + k. x² + 12x + 36 - 36 + 7.'),
              sa('Complete the square.\nx² - 5x', 'Expression:', key='(x - 2.5)² - 6.25', note='Form required: (x - h)² + k, with fractions or decimals: (x - {5/2})² - {25/4}.'),
              mc('What number completes the square for x² + {2/3}x?', ['{1/9}', '{1/3}', '{4/9}', '{2/3}'], note='Half of {2/3} is {1/3}, and ({1/3})² = {1/9}.'),
              tf('x² + bx + (b ÷ 2)² = (x + b ÷ 2)²', key=True, note='(x + b ÷ 2)² = x² + bx + b² ÷ 4.'),
              tf('To complete the square on 2x² + 8x, add 16 to the expression.', key=False, note='Factor 2 first: 2(x² + 4x + 4) - 8 = 2(x + 2)² - 8.'),
          ]),
          B('Solve literal equations for a variable', 'HSA-CED.A.4', [
              sa('Solve ax + b = 0 for x. (a ≠ 0)', 'x =', key='-b ÷ a', note='Any equivalent form.'),
              sa('Solve (x + p)² = q for x. (q ≥ 0)', 'x =', key='-p + √q or -p - √q', note='Form required: both solutions (x = -p ± √q).'),
              mc('Solve y = kx² for x, where k > 0 and y ≥ 0.', ['x = ±√(y ÷ k)', 'x = y ÷ k', 'x = ±√(ky)', 'x = √y ÷ k'], note='x² = y ÷ k, so x = ±√(y ÷ k).'),
              tf('Solving A = πr² for r (with r > 0) gives r = √(A ÷ π).', key=True, note='r² = A ÷ π, and r is positive.'),
              tf('Solving 2x - c = d for x gives x = (d - c) ÷ 2.', key=False, note='2x = c + d, so x = (c + d) ÷ 2.'),
          ]),
      ],
      f1=B('Use the quadratic formula when the discriminant is negative', 'HSN-CN.C.7', [
          sa('Use the quadratic formula to solve x² + 6x + 13 = 0. Write the solutions as a + bi.', 'Solutions:', key='x = -3 + 2i or x = -3 - 2i',
             note='Form required: a + bi (both). x = (-6 ± √(36 - 52)) ÷ 2 = (-6 ± 4i) ÷ 2.'),
          sa('Solve 2x² - 2x + 5 = 0. Write the solutions as a + bi.', 'Solutions:', key='x = 0.5 + 1.5i or x = 0.5 - 1.5i',
             note='Form required: a + bi (both), with fractions or decimals. x = (2 ± √(4 - 40)) ÷ 4 = (2 ± 6i) ÷ 4.'),
          mc('What is the discriminant of 3x² + x + 2?', ['-23', '25', '23', '-25'], note='1 - 4(3)(2) = 1 - 24 = -23.'),
          tf('When b² - 4ac < 0, the quadratic formula gives two complex solutions that are conjugates.', key=True, note='The ± gives p + qi and p - qi.'),
          tf('The solutions of x² + 9 = 0 are 3 and -3.', key=False, note='x² = -9, so x = 3i or x = -3i.'),
      ]),
      f2=B('Count the complex solutions of quadratic equations', 'HSN-CN.C.9', [
          sa('How many complex solutions, counted with multiplicity, does every quadratic equation have?', 'Answer:', key='2', note='Any equivalent form. A degree-2 polynomial has 2 complex zeros counted with multiplicity.'),
          sa('x² - 6x + 9 = 0 has one real solution. How is it counted by the Fundamental Theorem of Algebra?', 'Answer:', key='x = 3 is a double solution (multiplicity 2): (x - 3)² = 0.',
             note='Any equivalent explanation.'),
          mc('A quadratic equation with real coefficients has the solution 2 + i. What is its other solution?', ['2 - i', '-2 + i', '-2 - i', '2 + i again'],
             note='Nonreal solutions of real quadratics come in conjugate pairs.'),
          tf('Every quadratic equation with real coefficients has two solutions in the complex numbers, counted with multiplicity.', key=True, note='This is the Fundamental Theorem of Algebra for degree 2.'),
          tf('A quadratic equation can have three different complex solutions.', key=False, note='A degree-2 equation has at most 2 solutions.'),
      ])),

    # ------------------------------------------------------------------ A-REI.B.4.b (inspection, square roots, factoring)
