              sa('Solve 3x - 4 = 0.', 'x =', key='4/3', note='Any equivalent form, such as 1{1/3}. A rounded decimal is not exact.'),
              mc('Solve 5 - 2x = 0.', ['x = 2.5', 'x = -2.5', 'x = 5', 'x = 3'], note='-2x = -5, so x = 2.5.'),
