    # ------------------------------------------------------------------ A-REI.C.5 (both directions, new in 2.0.0)
    S('HSA-REI.C.5', 'Prove that replacing an equation by its sum with a multiple of the other gives an equivalent system, in both directions', num=72,
      main=[
          work('System A: x + 2y = 7 and 3x - y = 7. System B: x + 2y = 7 and 7x = 21, where 7x = 21 is the first equation plus 2 times the second.\nShow that every solution of A solves B and every solution of B solves A. Then give the solution.', 'Solution:',
               method='A to B: a solution of A makes both equations true, so adding x + 2y = 7 and 2(3x - y) = 14 gives 7x = 21. B to A: from 7x = 21 and x + 2y = 7, subtracting gives 6x - 2y = 14, so 3x - y = 7. The kept equation x + 2y = 7 is in both systems.',
               key='(3, 2)', note='Form required: both directions and the solution. Check: 3 + 4 = 7 and 9 - 2 = 7.'),
          work('Let P = c and Q = d be the two equations of a system (P and Q are expressions in x and y). Prove that the system P = c and Q + kP = d + kc has exactly the same solutions, for any number k.', 'Conclusion:',
               method='If (x, y) makes P = c and Q = d true, then Q + kP = d + kc (adding equal amounts), so it solves the new system. Conversely, if P = c and Q + kP = d + kc, subtracting kP = kc gives Q = d. So the solution sets are equal.',
               key='The two systems have the same solutions.', note='Form required: both directions, each with its reason.'),
          sa('Why must the new system keep one of the original equations unchanged? Give an example.', 'Answer:',
             key='The kept equation is needed to recover the replaced one. For example, replacing both x + y = 2 and x - y = 0 with their sum 2x = 2 alone loses information: 2x = 2 has infinitely many solutions (x = 1, any y), but the system has only (1, 1).',
             note='Any equivalent explanation with an example.'),
          mc('System: 2x + y = 5 and x - y = 1. Which step can produce a system with DIFFERENT solutions?', ['Replacing both equations by their sum, 3x = 6, alone',
             'Replacing the second equation by the sum of the two equations', 'Multiplying the first equation by 3', 'Writing the equations in the other order'],
             note='3x = 6 alone allows any y. The other steps keep the solution (2, 1).'),
          tf('If (2, 1) solves x + y = 3 and x - y = 1, then (2, 1) also solves (x + y) + 4(x - y) = 3 + 4(1).', key=True, note='3 + 4(1) = 7 on both sides.'),
      ],
      back=[
          B('Use the properties of equality to justify a step', 'HSA-REI.A.1', [
              sa('If P = c and Q = d are true, explain why P + Q = c + d is true.', 'Explanation:', key='Add Q to both sides of P = c to get P + Q = c + Q; since Q = d, replace Q by d on the right.',
                 note='Any equivalent explanation using the addition property and substitution.'),
              sa('If P + 3Q = c + 3d and Q = d, explain why P = c.', 'Explanation:', key='Since Q = d, 3Q = 3d. Subtracting equal amounts from both sides of P + 3Q = c + 3d gives P = c.',
                 note='Any equivalent explanation.'),
              mc('Which property justifies going from x - y = 1 to 4x - 4y = 4?', ['Multiplication property of equality', 'Addition property of equality', 'Commutative property', 'Substitution of y'],
                 note='Both sides are multiplied by 4.'),
              tf('Subtracting equal quantities from both sides of a true equation gives a true equation.', key=True, note='Subtraction property of equality.'),
              tf('If a + b = 10 and a = 4, then b = 14.', key=False, note='b = 10 - 4 = 6.'),
          ]),
          B('Solve simple systems by adding equations', '8.EE.C.8.b', [
              sa('Solve by adding the equations.\nx + y = 9\nx - y = 3', 'Solution:', key='(6, 3)', note='Any equivalent form. 2x = 12.'),
              sa('Solve.\n2x + y = 11\ny = 3', 'Solution:', key='(4, 3)', note='Any equivalent form. 2x = 8.'),
              mc('Solve.\nx + 2y = 8\nx = 2', ['(2, 3)', '(3, 2)', '(2, 5)', '(8, 0)'], note='2 + 2y = 8, so y = 3.'),
              tf('Adding x + y = 5 and x - y = 1 gives 2x = 6.', key=True, note='y and -y cancel.'),
              tf('The system x + y = 4 and 2x + 2y = 8 has exactly one solution.', key=False, note='The second equation is 2 times the first: infinitely many solutions.'),
          ]),
      ],
      f1=B('Use row operations on an augmented matrix as elimination steps', 'HSA-REI.C.8', [
          sa('Write the augmented matrix of the system x + 2y = 7 and 3x - y = 7.', 'Rows:', key='[1 2 | 7] and [3 -1 | 7]', note='Form required: both rows in order.'),
          sa('Apply R2 → 2R2 + R1 to the rows [1 2 | 7] and [3 -1 | 7]. What is the new second row, and which equation does it represent?', 'Answer:', key='[7 0 | 21], which is 7x = 21',
             note='Form required: the row and its equation. 2[3 -1 | 7] + [1 2 | 7].'),
          mc('Which row operation matches "replace equation 2 by itself minus 3 times equation 1"?', ['R2 → R2 - 3R1', 'R1 → R1 - 3R2', 'R2 → 3R2 - R1', 'R2 → R1'],
             note='Row 2 changes; row 1 is kept.'),
          tf('A row operation R2 → R2 + kR1 does not change the solutions of the system.', key=True, note='It is the elimination step proved in the MAIN section.'),
          tf('Replacing R2 by 0 · R2 + R1 keeps the solutions of every system.', key=False, note='It discards equation 2, so the solution set can grow.'),
      ]),
      f2=B('Solve the same system with an inverse matrix', 'HSA-REI.C.9', [
          sa('For x + 2y = 7 and 3x - y = 7, the coefficient matrix A has rows [1 2] and [3 -1]. Find the determinant of A.', 'Determinant:', key='-7', note='Any equivalent form. 1(-1) - 2(3) = -7.'),
          sa('A⁻¹ is (1 ÷ (-7)) times the matrix with rows [-1 -2] and [-3 1]. Use X = A⁻¹B, with B the column [7, 7], to solve the system.', 'Solution:', key='x = 3, y = 2',
             note='Form required: both values. (1 ÷ (-7)) times the column [-7 - 14, -21 + 7] = [3, 2].'),
          mc('If the determinant of the coefficient matrix of a 2-by-2 linear system is 0, which is true?', ['The system has no solution or infinitely many solutions.', 'The system has exactly one solution.',
             'X = A⁻¹B gives the solution.', 'The two equations must be identical.'], note='A has no inverse, so the system does not have exactly one solution.'),
          tf('Solving AX = B with X = A⁻¹B gives the same solution as elimination.', key=True, note='Both methods find the one solution when A has an inverse.'),
          tf('For all 2-by-2 matrices A and B, A⁻¹B = BA⁻¹.', key=False, note='Matrix multiplication is not commutative in general.'),
      ])),

